import type { TooltipPosition } from './Tooltip.types';

export const TOOLTIP_TEXT_ALIGN_BY_POSITION: Record<
  TooltipPosition,
  'center' | 'left' | 'right'
> = {
  top: 'center',
  bottom: 'center',
  left: 'right',
  right: 'left',
};

export const TOOLTIP_DELAY_MS = 300;
export const TOOLTIP_SIDE_OFFSET = 8;
export const TOOLTIP_COLLISION_PADDING = 8;
export const TOOLTIP_MAX_WIDTH = '256px';
